1	@import "tailwindcss";
2	
3	@theme {
4	  /* Brand typeface (Geist), injected as CSS vars by next/font in app/layout.tsx.
5	     Mapping them here makes Tailwind's `font-sans` / `font-mono` utilities — and the
6	     body default below — resolve to Geist, with a graceful system fallback. */
7	  --font-sans: var(--font-geist-sans), ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
8	  --font-mono: var(--font-geist-mono), ui-monospace, "SFMono-Regular", "Menlo", monospace;
9	
10	  --color-brand-50: #f2f0ff;
11	  --color-brand-100: #e4e0ff;
12	  --color-brand-200: #c9c2ff;
13	  --color-brand-300: #a89aff;
14	  --color-brand-400: #8a70fb;
15	  --color-brand-500: #6f47f5;
16	  --color-brand-600: #5f2ee8;
17	  --color-brand-700: #5124c4;
18	  --color-brand-800: #421fa0;
19	  --color-brand-900: #371d7f;
20	
21	  --color-navy-950: #060a14;
22	  --color-navy-900: #0a101f;
23	  --color-navy-850: #0d1526;
24	  --color-navy-800: #111a30;
25	  --color-navy-700: #1a2540;
26	  --color-navy-600: #253354;
27	
28	  --color-accent-blue: #3b82f6;
29	  --color-accent-cyan: #22d3ee;
30	
31	  --animate-fade-up: fade-up 0.4s ease-out both;
32	  --animate-pulse-dot: pulse-dot 2s ease-in-out infinite;
33	
34	  /* Admin attention indicators (components/admin/AdminIndicators.tsx). `bell-shake`
35	     runs once whenever a new ticket / live-chat reply / email arrives; opt-in via
36	     `motion-safe:` at the call site so reduced-motion users just see the badge. */
37	  --animate-bell-shake: bell-shake 0.9s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
38	  @keyframes bell-shake {
39	    0%, 100% { transform: rotate(0); }
40	    10%, 50%, 90% { transform: rotate(-11deg); }
41	    30%, 70% { transform: rotate(11deg); }
42	  }
43	
44	  /* Pricing explorer interactions. `price-pop` runs on every billing-cycle change
45	     (re-keyed number), `panel-in` on every product-tab switch. Both are opt-in via
46	     `motion-safe:` at the call site, so reduced-motion users see the resting frame. */
47	  --animate-price-pop: price-pop 0.42s cubic-bezier(0.22, 1, 0.36, 1) both;
48	  --animate-panel-in: panel-in 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
49	  /* Reverse of panel-in — used when <ChatWidget/>'s panel closes, so it settles
50	     away instead of just vanishing. Shorter and eased the opposite direction
51	     (ease-in, ends abruptly) since a close should feel snappier than an open. */
52	  --animate-panel-out: panel-out 0.22s cubic-bezier(0.4, 0, 1, 1) both;
53	
54	  @keyframes price-pop {
55	    from { opacity: 0; transform: translateY(7px); filter: blur(3px); }
56	    to { opacity: 1; transform: translateY(0); filter: blur(0); }
57	  }
58	  @keyframes panel-in {
59	    from { opacity: 0; transform: translateY(12px) scale(0.994); }
60	    to { opacity: 1; transform: translateY(0) scale(1); }
61	  }
62	  @keyframes panel-out {
63	    from { opacity: 1; transform: translateY(0) scale(1); }
64	    to { opacity: 0; transform: translateY(10px) scale(0.98); }
65	  }
66	  /* GameHero logo entrance — a soft pop as the themed hero mounts. Applied via
67	     the `motion-safe:animate-gh-pop` utility so reduced-motion users see no motion. */
68	  @keyframes gh-pop {
69	    from { opacity: 0; transform: translateY(10px) scale(0.9); }
70	    to { opacity: 1; transform: translateY(0) scale(1); }
71	  }
72	  --animate-gh-pop: gh-pop 0.6s cubic-bezier(0.22, 1, 0.36, 1) both;
73	
74	  /* Showcase mock-screen animations (marketing product pages). All are opt-in
75	     via Tailwind's `motion-safe:` variant, so reduced-motion users see the final
76	     resting state (bars full, lines visible) with no motion. */
77	  --animate-grow-up: grow-up 0.9s cubic-bezier(0.22, 1, 0.36, 1) both;
78	  --animate-grow-x: grow-x 1.1s cubic-bezier(0.22, 1, 0.36, 1) both;
79	  --animate-eq: eq 1.7s ease-in-out infinite;
80	  --animate-blink: blink 1.1s steps(1) infinite;
81	  --animate-sweep: sweep 3.4s ease-in-out infinite;
82	  --animate-line-in: line-in 0.55s cubic-bezier(0.22, 1, 0.36, 1) both;
83	
84	  @keyframes fade-up {
85	    from { opacity: 0; transform: translateY(8px); }
86	    to { opacity: 1; transform: translateY(0); }
87	  }
88	  @keyframes pulse-dot {
89	    0%, 100% { box-shadow: 0 0 0 0 rgb(52 211 153 / 0.5); }
90	    50% { box-shadow: 0 0 0 5px rgb(52 211 153 / 0); }
91	  }
92	  /* One-shot bar grow (origin at the base). Resting state = full. */
93	  @keyframes grow-up {
94	    from { transform: scaleY(0.06); }
95	    to { transform: scaleY(1); }
96	  }
97	  /* One-shot progress/usage fill. Resting state = full width. */
98	  @keyframes grow-x {
99	    from { transform: scaleX(0); }
100	    to { transform: scaleX(1); }
101	  }
102	  /* Continuous "live traffic" equaliser pulse. Resting state = full height. */
103	  @keyframes eq {
104	    0%, 100% { transform: scaleY(0.35); }
105	    50% { transform: scaleY(1); }
106	  }
107	  /* Terminal cursor blink. Resting state = visible. */
108	  @keyframes blink {
109	    0%, 49% { opacity: 1; }
110	    50%, 100% { opacity: 0; }
111	  }
112	  /* Soft light sweep across a chart/highlight. */
113	  @keyframes sweep {
114	    0% { transform: translateX(-120%); opacity: 0; }
115	    40%, 60% { opacity: 0.7; }
116	    100% { transform: translateX(320%); opacity: 0; }
117	  }
118	  /* Staggered line/row reveal. Resting state = visible. */
119	  @keyframes line-in {
120	    from { opacity: 0; transform: translateY(6px); }
121	    to { opacity: 1; transform: translateY(0); }
122	  }
123	
124	  /* Post-payment provisioning/success screen (ProvisioningOverlay). All
125	     opt-in via `motion-safe:`, so reduced-motion users see the resting frame
126	     (full ring / checkmark drawn / settled position) with no motion. */
127	  --animate-orbit-spin: orbit-spin 1.4s linear infinite;
128	  --animate-check-pop: check-pop 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
129	  --animate-check-draw: check-draw 0.4s 0.2s ease-out both;
130	  --animate-ring-glow: ring-glow 2.4s ease-in-out infinite;
131	
132	  /* Continuous loader ring — a single arc rotating around the icon. Resting
133	     state = arc visible at its start position (no motion). */
134	  @keyframes orbit-spin {
135	    from { transform: rotate(0deg); }
136	    to { transform: rotate(360deg); }
137	  }
138	  /* Success badge pop-in (runs once the icon swaps from spinner to check). */
139	  @keyframes check-pop {
140	    0% { opacity: 0; transform: scale(0.5); }
141	    70% { transform: scale(1.08); }
142	    100% { opacity: 1; transform: scale(1); }
143	  }
144	  /* Checkmark stroke draw, timed to start just after check-pop settles. */
145	  @keyframes check-draw {
146	    from { stroke-dashoffset: 24; }
147	    to { stroke-dashoffset: 0; }
148	  }
149	  /* Slow ambient glow behind the provisioning icon. Resting state = mid-glow. */
150	  @keyframes ring-glow {
151	    0%, 100% { opacity: 0.5; }
152	    50% { opacity: 1; }
153	  }
154	}
155	
156	body {
157	  @apply bg-navy-950 text-slate-100 antialiased font-sans;
158	  background-image:
159	    radial-gradient(ellipse 80% 50% at 20% -10%, rgb(111 71 245 / 0.13), transparent),
160	    radial-gradient(ellipse 60% 40% at 90% 0%, rgb(59 130 246 / 0.10), transparent);
161	  background-attachment: fixed;
162	}
163	
164	::-webkit-scrollbar { width: 10px; height: 10px; }
165	::-webkit-scrollbar-track { background: transparent; }
166	::-webkit-scrollbar-thumb { background: #253354; border-radius: 8px; border: 2px solid #060a14; }
167	::-webkit-scrollbar-thumb:hover { background: #34456e; }
168	
169	@layer components {
170	  /* Surfaces */
171	  .card {
172	    @apply rounded-2xl border border-white/[0.06] bg-navy-900/70 p-6 backdrop-blur-md;
173	    box-shadow: 0 1px 0 0 rgb(255 255 255 / 0.03) inset, 0 8px 32px -12px rgb(0 0 0 / 0.5);
174	  }
175	  .card-hover {
176	    @apply transition-all duration-200 hover:border-brand-500/30 hover:bg-navy-850/80;
177	  }
178	  .glass {
179	    @apply rounded-2xl border border-white/[0.08] bg-white/[0.03] backdrop-blur-xl;
180	  }
181	  .glow-brand {
182	    box-shadow: 0 0 40px -8px rgb(111 71 245 / 0.35);
183	  }
184	  /* The auth-card glow ring — ported directly from Kodely's PromptHero
185	     "chasing light" ring (components/marketing/PromptHero.tsx +
186	     app/globals.css there), recoloured to Nxeon's blue -> violet -> cyan
187	     family instead of Kodely's pink/purple/orange. Same technique, kept
188	     intact rather than reinvented:
189	     - Each layer is a STATIC outer clipper (.glow-clip-a/-b, position, plain
190	       overflow:hidden, never transforms) containing one OVERSIZED inner
191	       rotator (.glow-spin-a/-b, a 200%-wide square via SPIN_SQUARE in
192	       AuthShell.tsx, centered) carrying the conic-gradient background. Only
193	       the inner rotator spins via plain `transform: rotate()`; being
194	       oversized, its corners sweeping outside a same-sized box never matter
195	       because the static outer clipper crops them at every angle.
196	     - The blur lives on the CLIP element, not the rotating child, because
197	       filters apply after the element's own overflow:hidden clipping — that
198	       ordering is what lets the light bleed softly past the clip's edge
199	       instead of surviving as a hard-edged ring.
200	     - The card sitting on top (relative z-10, opaque) covers the rotator's
201	       entire interior, leaving only the outer few px visible as a ring.
202	     - Entrance fade-in, then a slow ambient pulse picking up from the same
203	       opacity the fade-in settled on (no jump at the handoff). */
204	  @keyframes glow-spin {
205	    to {
206	      transform: rotate(360deg);
207	    }
208	  }
209	  .glow-spin-a {
210	    animation: glow-spin 9s linear infinite;
211	  }
212	  .glow-spin-b {
213	    animation: glow-spin 14s linear infinite reverse;
214	  }
215	  @keyframes glow-fade-in-a {
216	    from {
217	      opacity: 0;
218	      transform: scale(0.94);
219	    }
220	    to {
221	      opacity: 0.22;
222	      transform: scale(1);
223	    }
224	  }
225	  @keyframes glow-fade-in-b {
226	    from {
227	      opacity: 0;
228	      transform: scale(0.94);
229	    }
230	    to {
231	      opacity: 0.13;
232	      transform: scale(1);
233	    }
234	  }
235	  @keyframes glow-pulse-a {
236	    0%,
237	    100% {
238	      opacity: 0.22;
239	    }
240	    50% {
241	      opacity: 0.32;
242	    }
243	  }
244	  @keyframes glow-pulse-b {
245	    0%,
246	    100% {
247	      opacity: 0.13;
248	    }
249	    50% {
250	      opacity: 0.21;
251	    }
252	  }
253	  .glow-clip-a {
254	    animation:
255	      glow-fade-in-a 0.8s cubic-bezier(0.16, 1, 0.3, 1) both,
256	      glow-pulse-a 4.5s ease-in-out 0.8s infinite;
257	  }
258	  .glow-clip-b {
259	    animation:
260	      glow-fade-in-b 0.9s cubic-bezier(0.16, 1, 0.3, 1) 0.1s both,
261	      glow-pulse-b 6s ease-in-out 1s infinite;
262	  }
263	  @media (prefers-reduced-motion: reduce) {
264	    .glow-spin-a,
265	    .glow-spin-b {
266	      animation: none;
267	    }
268	    .glow-clip-a {
269	      animation: none;
270	      opacity: 0.22;
271	    }
272	    .glow-clip-b {
273	      animation: none;
274	      opacity: 0.13;
275	    }
276	  }
277	  /* Subtle outer glow for the deploy wizard's outer container — same violet→cyan
278	     brand pair as .hero-aura / DeployHub's tile glows, just restrained: a checkout
279	     flow, not a marketing hero. Self-contained (restates .card's own shadow layers
280	     plus two soft ambient glow layers) so it doesn't depend on CSS source order
281	     when applied alongside .card. */
282	  .wizard-shell {
283	    box-shadow:
284	      0 1px 0 0 rgb(255 255 255 / 0.03) inset,
285	      0 8px 32px -12px rgb(0 0 0 / 0.5),
286	      0 0 60px -22px rgb(111 71 245 / 0.35),
287	      0 0 90px -36px rgb(34 211 238 / 0.22);
288	  }
289	
290	  /* Typography */
291	  .grad-text {
292	    @apply bg-gradient-to-r from-accent-blue via-brand-400 to-brand-500 bg-clip-text text-transparent;
293	  }
294	  .page-title {
295	    @apply text-2xl font-bold tracking-tight;
296	  }
297	  .section-label {
298	    @apply text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-500;
299	  }
300	
301	  /* Buttons */
302	  .btn-primary,
303	  .btn-secondary,
304	  .btn-danger,
305	  .btn-ghost,
306	  .btn-deploy {
307	    @apply inline-flex cursor-pointer items-center justify-center gap-2 rounded-xl px-4 py-2 text-sm font-semibold transition-all duration-150 disabled:cursor-not-allowed disabled:opacity-50;
308	  }
309	  .btn-primary {
310	    @apply bg-gradient-to-r from-accent-blue to-brand-500 text-white hover:brightness-110;
311	    box-shadow: 0 4px 20px -6px rgb(111 71 245 / 0.5);
312	  }
313	  /* The sleek, unified "Deploy" CTA used across every service page. Animated
314	     gradient-shift + a one-shot shimmer sweep on hover + an arrow nudge. */
315	  @keyframes btn-deploy-sweep {
316	    0% { transform: translateX(-130%) skewX(-12deg); }
317	    100% { transform: translateX(130%) skewX(-12deg); }
318	  }
319	  .btn-deploy {
320	    @apply relative overflow-hidden rounded-full px-5 text-white;
321	    background-image: linear-gradient(110deg, var(--color-brand-500), var(--color-accent-blue), var(--color-accent-cyan), var(--color-brand-500));
322	    background-size: 220% 100%;
323	    background-position: 0% 0;
324	    box-shadow: 0 8px 26px -8px rgb(111 71 245 / 0.55), inset 0 1px 0 0 rgb(255 255 255 / 0.18);
325	    transition: transform 0.2s ease, box-shadow 0.2s ease, background-position 0.6s ease;
326	  }
327	  .btn-deploy:hover {
328	    transform: translateY(-1px);
329	    background-position: 100% 0;
330	    box-shadow: 0 12px 34px -8px rgb(111 71 245 / 0.7), inset 0 1px 0 0 rgb(255 255 255 / 0.25);
331	  }
332	  .btn-deploy::before {
333	    content: "";
334	    position: absolute;
335	    top: 0;
336	    bottom: 0;
337	    left: 0;
338	    width: 60%;
339	    background: linear-gradient(90deg, transparent, rgb(255 255 255 / 0.38), transparent);
340	    transform: translateX(-130%) skewX(-12deg);
341	    pointer-events: none;
342	  }
343	  .btn-deploy:hover::before {
344	    animation: btn-deploy-sweep 0.75s ease;
345	  }
346	  .btn-deploy .dep-arrow {
347	    transition: transform 0.25s ease;
348	  }
349	  .btn-deploy:hover .dep-arrow {
350	    transform: translateX(3px);
351	  }
352	  @media (prefers-reduced-motion: reduce) {
353	    .btn-deploy,
354	    .btn-deploy:hover {
355	      transition: none;
356	    }
357	    .btn-deploy:hover::before {
358	      animation: none;
359	    }
360	    .btn-deploy:hover .dep-arrow {
361	      transform: none;
362	    }
363	  }
364	  .btn-secondary {
365	    @apply border border-white/10 bg-white/[0.04] text-slate-100 hover:border-white/20 hover:bg-white/[0.08];
366	  }
367	  .btn-danger {
368	    @apply border border-red-500/30 bg-red-500/10 text-red-300 hover:bg-red-500/20;
369	  }
370	  .btn-ghost {
371	    @apply text-slate-400 hover:bg-white/[0.05] hover:text-white;
372	  }
373	
374	  /* Forms */
375	  .input {
376	    @apply w-full rounded-xl border border-white/10 bg-navy-900/80 px-3.5 py-2.5 text-sm text-slate-100 outline-none transition-colors placeholder:text-slate-500 focus:border-brand-400/60 focus:ring-2 focus:ring-brand-500/20;
377	  }
378	  .label {
379	    @apply mb-1.5 block text-xs font-medium uppercase tracking-wide text-slate-400;
380	  }
381	
382	  /* Nav */
383	  .nav-item {
384	    @apply flex items-center gap-3 rounded-xl px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:bg-white/[0.05] hover:text-white;
385	  }
386	  .nav-item-active {
387	    @apply bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white;
388	    box-shadow: 0 4px 16px -6px rgb(111 71 245 / 0.6);
389	  }
390	
391	  /* Tables */
392	  .table-shell {
393	    @apply w-full text-sm;
394	  }
395	  .table-shell thead th {
396	    @apply px-4 py-3 text-left text-[11px] font-semibold uppercase tracking-wider text-slate-500;
397	  }
398	  .table-shell tbody tr {
399	    @apply border-t border-white/[0.05] transition-colors hover:bg-white/[0.02];
400	  }
401	  .table-shell tbody td {
402	    @apply px-4 py-3;
403	  }
404	
405	  /* Misc */
406	  .kbd {
407	    @apply rounded-md border border-white/10 bg-white/[0.06] px-1.5 py-0.5 font-mono text-[11px] text-slate-400;
408	  }
409	  .divider {
410	    @apply my-4 border-t border-white/[0.06];
411	  }
412	  .skeleton {
413	    @apply animate-pulse rounded-lg bg-white/[0.06];
414	  }
415	
416	  /* ── Marketing design system (v2 redesign) ─────────────────────────────────
417	     Shared primitives so every page reads as one designed site. The Section
418	     component alternates these background "tones" to give the long pages rhythm
419	     instead of a flat stack. Colors/animations are the existing brand system. */
420	
421	  /* Eyebrow label above section/hero headings (the ubiquitous uppercase tag). */
422	  .eyebrow {
423	    @apply inline-flex items-center gap-2 text-[12px] font-semibold uppercase tracking-[0.16em] text-brand-300;
424	  }
425	  .eyebrow-pill {
426	    @apply inline-flex items-center gap-2 rounded-full border border-brand-500/20 bg-brand-500/[0.08] px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.14em] text-brand-200;
427	  }
428	
429	  /* Section background tones for alternating rhythm. "panel" is a hair lighter
430	     than the page with hairline separators; "deep" recedes. Replaces one-off
431	     inline gradients scattered across pages. */
432	  .tone-panel {
433	    @apply border-y border-white/[0.05] bg-navy-900/40;
434	  }
435	  .tone-deep {
436	    background: linear-gradient(180deg, rgb(6 10 20 / 0) 0%, rgb(8 12 24 / 0.6) 50%, rgb(6 10 20 / 0) 100%);
437	  }
438	
439	  /* Foreground tokens so tone-aware primitives (SectionTitle, FeatureCard) flip
440	     text automatically. Default = the dark theme's light text. */
441	  :root {
442	    --fg: #ffffff;
443	    --fg-muted: #94a3b8; /* slate-400 */
444	  }
445	
446	  /* "light" tone — a rare, deliberate light band to break up the dark theme and
447	     divide long pages (used sparingly, ~one per page). Flips the foreground
448	     tokens to dark and restyles surfaces/buttons inside so everything stays
449	     legible without touching each call site. */
450	  .tone-light {
451	    @apply border-y border-slate-200/70 text-slate-700;
452	    background: linear-gradient(180deg, #f4f3fb 0%, #ebe9f5 100%);
453	    --fg: #0f172a;       /* slate-900 */
454	    --fg-muted: #475569; /* slate-600 */
455	  }
456	  .tone-light .card {
457	    @apply border-slate-200 bg-white text-slate-700;
458	    box-shadow: 0 1px 2px rgb(15 23 42 / 0.05), 0 16px 36px -20px rgb(15 23 42 / 0.22);
459	  }
460	  .tone-light .card-hover:hover {
461	    @apply border-brand-500/40 bg-white;
462	  }
463	  .tone-light .glass {
464	    @apply border-slate-200 bg-white/70;
465	  }
466	  .tone-light .section-label {
467	    @apply text-slate-500;
468	  }
469	  .tone-light .btn-secondary {
470	    @apply border-slate-300 bg-white text-slate-800 hover:border-slate-400 hover:bg-slate-50;
471	  }
472	  .tone-light .btn-ghost {
473	    @apply text-slate-600 hover:bg-slate-900/[0.06] hover:text-slate-900;
474	  }
475	
476	  /* Reusable hero aura — the dual-radial violet/blue glow that ~10 sub-page
477	     heroes previously inlined by hand. Sits in an absolutely-positioned layer. */
478	  .hero-aura {
479	    background-image:
480	      radial-gradient(ellipse 70% 60% at 15% 0%, rgb(111 71 245 / 0.20), transparent 70%),
481	      radial-gradient(ellipse 60% 50% at 90% 10%, rgb(59 130 246 / 0.14), transparent 70%);
482	  }
483	
484	  /* Soft violet lift on hover for interactive cards (was inline arbitrary shadow). */
485	  .lift {
486	    @apply transition-all duration-200 hover:-translate-y-0.5 hover:border-brand-500/30;
487	    &:hover { box-shadow: 0 18px 40px -20px rgb(111 71 245 / 0.45); }
488	  }
489	
490	  /* Consistent max-width content rail. */
491	  .rail {
492	    @apply mx-auto max-w-6xl px-5 sm:px-6;
493	  }
494	
495	  /* Top-nav dropdown trigger button. */
496	  .nav-trigger {
497	    @apply inline-flex cursor-pointer items-center gap-1 rounded-lg px-3 py-2 text-sm font-medium text-slate-400 transition-colors hover:text-white;
498	  }
499	  .nav-trigger.is-open {
500	    @apply text-white;
501	  }
502	
503	  /* Animated gradient underline that wipes in on hover (rocket-style nav). Sits
504	     inside the px-3 padding so it tracks the label width. */
505	  .nav-underline {
506	    position: relative;
507	  }
508	  .nav-underline::after {
509	    content: "";
510	    position: absolute;
511	    left: 12px;
