99	export function TaskFeed({ accountId, active, onTasks }: { accountId: string; active: boolean; onTasks?: (t: TaskView[]) => void }) {
100	  const [tasks, setTasks] = useState<TaskView[]>([]);
101	  useEffect(() => {
102	    if (!active) return;
103	    let stop = false;
104	    const load = () => listHostingTasks(accountId).then((t) => { if (!stop) { setTasks(t); onTasks?.(t); } }).catch(() => {});
105	    load();
106	    const timer = setInterval(load, 5000);
107	    return () => { stop = true; clearInterval(timer); };
108	    // eslint-disable-next-line react-hooks/exhaustive-deps
109	  }, [accountId, active]);
110	  // Adminer (INSTALL_DBTOOL) is retired — Nxeon DB Studio is the only DB manager now.
111	  // Hide its task rows entirely, incl. stale FAILED ones (e.g. the old download 404),
112	  // so a dead fallback never surfaces an error on the account overview.
113	  const visible = tasks.filter((t) => t.kind !== "INSTALL_DBTOOL" && (t.status !== "DONE" || t.result || t.error));
114	  if (!visible.length) return null;
115	  const label: Record<string, string> = {
116	    PHP_SWITCH: "PHP version", WORDPRESS_INSTALL: "WordPress install", APP_INSTALL: "App install", BACKUP: "Backup", RESTORE: "Restore",
117	    CREATE_SUBDOMAIN: "Subdomain", DELETE_SUBDOMAIN: "Subdomain removal", CREATE_ADDON_DOMAIN: "Addon domain", DELETE_ADDON_DOMAIN: "Domain removal", CREATE_CRON: "Cron job", DELETE_CRON: "Cron removal",
118	    INSTALL_DBTOOL: "Database manager", ENSURE_DBMGR: "Database manager", APPLY_PLAN_LIMITS: "Plan update",
119	    SET_PRIMARY_DOMAIN: "Primary domain",
120	  };
121	  return (
122	    <div className="space-y-1 text-xs">
123	      {visible.map((t) => {
124	        const wp = t.kind === "WORDPRESS_INSTALL" && t.result ? safeJson(t.result) : null;
125	        const app = t.kind === "APP_INSTALL" && t.result ? safeJson(t.result) : null;
126	        return (
127	          <div key={t.id} className={t.status === "FAILED" ? "text-red-300" : t.status === "DONE" ? "text-emerald-300" : "text-amber-300"}>
128	            {label[t.kind] ?? t.kind}: {t.status.toLowerCase()}{t.error ? ` — ${t.error}` : ""}
129	            {wp && (
130	              <div className="mt-0.5 rounded border border-emerald-500/30 bg-emerald-500/10 px-2 py-1 text-emerald-200">
131	                WordPress installed — log in at <span className="font-mono">{wp.url}</span> · user <span className="font-mono">{wp.adminUser}</span> · password{" "}
132	                <span className="font-mono">{wp.adminPassword}</span> <span className="opacity-80">(also saved under App credentials)</span>
