258	/**
259	 * DNS→HTTPS stepper driven by the REAL serve-verification the worker records
260	 * (serveHttpOk / serveHttpsOk / sslActive), so it can never claim "live" while
261	 * HTTPS actually refuses. Three overall states, per the account's measured health:
262	 *   • verified — a trusted cert is live (sslActive) and 443 answers → "HTTPS live ✓"
263	 *   • issuing  — the site answers (self-signed 443 or HTTP) but no trusted cert yet
264	 *   • dns      — nothing answers for the domain yet (DNS not pointed at us)
265	 */
266	function DnsStepper({ account }: { account: HostingAccountView }) {
267	  const checked = account.healthCheckedAt != null || account.serveHttpOk != null;
268	  const serving = account.serveHttpOk === true || account.serveHttpsOk === true;
269	  const verified = account.sslActive && account.serveHttpsOk !== false;
270	  const state: "verified" | "issuing" | "dns" | "pending" =
271	    verified ? "verified" : serving ? "issuing" : checked ? "dns" : "pending";
272	
273	  const free = account.isFreeSubdomain;
274	  const steps = [
275	    { label: free ? "DNS ready" : "Point domain", done: true, hint: free ? "Set up automatically" : "Add the A record above" },
276	    {
277	      label: "Site live",
278	      done: state === "issuing" || state === "verified",
279	      hint: state === "issuing" || state === "verified" ? "Serving traffic" : state === "dns" ? "DNS not detected yet" : "Checking…",
280	    },
281	    {
282	      label: "HTTPS verified",
283	      done: state === "verified",
284	      hint: state === "verified" ? "Certificate trusted" : state === "issuing" ? "Issuing certificate" : "Auto after DNS",
285	    },
286	  ];
287	
288	  const headline =
289	    account.healthNote ??
290	    (state === "verified" ? "HTTPS live — verified" : state === "issuing" ? "HTTP live, HTTPS issuing" : state === "dns" ? "DNS not detected yet" : "Not checked yet");
291	  const headlineTone = state === "verified" ? "text-emerald-300" : state === "dns" ? "text-slate-400" : "text-amber-300";
292	
293	  return (
294	    <div className="mt-4">
295	      <div className="flex items-center">
296	        {steps.map((s, i) => (
297	          <div key={s.label} className="flex flex-1 items-center last:flex-none">
298	            <div className="flex flex-col items-center">
299	              <span className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] ${s.done ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300" : "border-amber-500/40 bg-amber-500/10 text-amber-300"}`}>
300	                {s.done ? "✓" : i + 1}
301	              </span>
302	            </div>
303	            {i < steps.length - 1 && <div className={`mx-2 h-px flex-1 ${steps[i + 1].done ? "bg-emerald-500/40" : "bg-white/10"}`} />}
304	          </div>
305	        ))}
306	      </div>
307	      <div className="mt-1.5 flex items-start justify-between text-[11px]">
308	        {steps.map((s) => (
309	          <div key={s.label} className="flex-1 text-center first:text-left last:text-right">
310	            <p className={s.done ? "text-emerald-300" : "text-slate-400"}>{s.label}</p>
311	            <p className="text-slate-500">{s.hint}</p>
312	          </div>
313	        ))}
314	      </div>
315	      <p className={`mt-3 text-xs font-medium ${headlineTone}`}>
316	        {headline}
317	        {account.healthCheckedAt && (
318	          <span className="ml-1 font-normal text-slate-500">· checked {new Date(account.healthCheckedAt).toLocaleTimeString()}</span>
319	        )}
320	      </p>
321	      {state !== "verified" && (
322	        <p className="mt-1 text-xs text-slate-500">
323	          {free ? (
324	            <>A trusted HTTPS certificate is issued automatically once provisioning completes — this usually takes a minute. Use <span className="text-slate-300">Refresh</span> to check right away.</>
325	          ) : (
326	            <>A trusted HTTPS certificate is issued automatically once your domain resolves to us — this can take a few minutes after you set the DNS record. Use <span className="text-slate-300">Go live</span> to check right away.</>
327	          )}
328	        </p>
329	      )}
330	    </div>
331	  );
332	}
