10	/**
11	 * Persistent, always-visible header for the game-server panel.
12	 *
13	 * Shows identity + live vitals (players / CPU / RAM / disk) with glowing status
14	 * and animated micro-graphs, and keeps Connect / Restart / Stop reachable from
15	 * every tab. Power buttons call the ownership-guarded `gamePower` action; the
16	 * micro-graphs poll /api/metrics for shape (values themselves come from the
17	 * server-rendered snapshot, so the numbers are always truthful).
18	 */
19	
20	const STATUS_TONE: Record<string, { dot: string; glow: string; label: string }> = {
21	  RUNNING: { dot: "#34d399", glow: "0 0 10px 1px rgba(52,211,153,0.7)", label: "Online" },
22	  STOPPED: { dot: "#f87171", glow: "0 0 10px 1px rgba(248,113,113,0.6)", label: "Offline" },
23	  SUSPENDED: { dot: "#fbbf24", glow: "0 0 10px 1px rgba(251,191,36,0.6)", label: "Suspended" },
24	  PROVISIONING: { dot: "#60a5fa", glow: "0 0 10px 1px rgba(96,165,250,0.7)", label: "Deploying" },
25	  PENDING: { dot: "#60a5fa", glow: "0 0 10px 1px rgba(96,165,250,0.7)", label: "Deploying" },
26	  ERROR: { dot: "#f87171", glow: "0 0 10px 1px rgba(248,113,113,0.6)", label: "Error" },
27	};
