29	/** Deterministic gentle wave around a base value — a placeholder trend that
30	 *  always looks alive even before RRD history is available. */
31	function seedWave(base: number, seed: number): number[] {
32	  const out: number[] = [];
33	  for (let i = 0; i < 24; i++) {
34	    const n = Math.sin((i + seed) * 0.7) * 0.12 + Math.sin((i + seed) * 1.9) * 0.05;
35	    out.push(Math.max(0, base * (1 + n)));
36	  }
37	  return out;
38	}
39	
40	export function GamePanelHeader({ serverId, gameFamily, data }: { serverId: string; gameFamily: string; data: GameHeaderData }) {
41	  const [copied, setCopied] = useState<string | false>(false);
42	  const [err, setErr] = useState<string | null>(null);
43	  const [pending, start] = useTransition();
44	  const [playersOnline, setPlayersOnline] = useState(data.players.online);
45	  const [cpuSeries, setCpuSeries] = useState<number[]>(() => seedWave(data.cpuPct, 1));
46	  const [memSeries, setMemSeries] = useState<number[]>(() =>
47	    seedWave(data.mem.maxBytes ? (data.mem.usedBytes / data.mem.maxBytes) * 100 : 40, 5)
48	  );
49	  const copyTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
50	
51	  const tone = STATUS_TONE[data.status] ?? STATUS_TONE.STOPPED;
52	  const diskPct = data.disk.maxGB ? (data.disk.usedGB / data.disk.maxGB) * 100 : 0;
53	
54	  // The primary connect address to copy — prefer verified custom domain.
55	  const primaryConnect = data.customDomainVerified && data.customDomain
56	    ? data.customDomain
57	    : data.connect;
58	
59	  // Poll live player count via RCON `list` command.
60	  useEffect(() => {
61	    if (!data.running) return;
62	    let alive = true;
63	    const poll = async () => {
64	      const r = await getGamePlayers(serverId).catch(() => null);
65	      if (alive && r?.ok) setPlayersOnline(r.players.length);
66	    };
67	    void poll();
68	    const t = setInterval(poll, 15000);
69	    return () => { alive = false; clearInterval(t); };
70	  }, [serverId, data.running]);
71	
72	  // Poll real RRD history for graph shape (values shown remain the truthful
73	  // server snapshot). Silently falls back to the seeded wave on any failure.
74	  useEffect(() => {
75	    if (!data.running) return;
76	    let alive = true;
77	    const load = async () => {
78	      try {
79	        const res = await fetch(`/api/metrics?serverId=${serverId}&tf=hour`, { cache: "no-store" });
80	        if (!res.ok) return;
81	        const json: { data?: { cpu: number | null; mem: number | null; maxmem: number | null }[] } =
82	          await res.json();
83	        const rows = (json.data ?? []).slice(-24);
84	        if (!alive || rows.length < 3) return;
85	        setCpuSeries(rows.map((r) => (r.cpu ?? 0) * 100));
86	        setMemSeries(rows.map((r) => (r.mem && r.maxmem ? (r.mem / r.maxmem) * 100 : 0)));
87	      } catch {
88	        /* keep the seeded wave */
89	      }
90	    };
91	    void load();
92	    const t = setInterval(load, 15000);
93	    return () => {
94	      alive = false;
95	      clearInterval(t);
96	    };
97	  }, [serverId, data.running]);
98	
99	  function copyAddr(addr: string) {
100	    void navigator.clipboard?.writeText(addr);
101	    setCopied(addr);
102	    if (copyTimer.current) clearTimeout(copyTimer.current);
103	    copyTimer.current = setTimeout(() => setCopied(false), 1600);
104	  }
105	
106	  function copyConnect() {
107	    if (!primaryConnect) return;
108	    copyAddr(primaryConnect);
109	  }
110	
111	  function power(action: "restart" | "stop") {
112	    if (action === "stop" && !window.confirm("Stop the game server? Players will be disconnected.")) return;
113	    setErr(null);
114	    start(async () => {
115	      const r = await gamePower(serverId, action);
116	      if (!r.ok) setErr(r.error);
117	    });
118	  }
119	
120	  const disabled = pending || !data.canControl || !data.running;
121	
122	  return (
123	    <div className="relative overflow-hidden rounded-3xl border border-white/[0.07] bg-gradient-to-br from-navy-900/90 via-navy-950/80 to-navy-900/70 p-6 shadow-[0_20px_60px_-30px_rgba(111,71,245,0.5)] backdrop-blur-xl">
124	      {/* ambient aura */}
125	      <div
126	        aria-hidden
127	        className="pointer-events-none absolute -right-24 -top-24 h-64 w-64 rounded-full opacity-40 blur-3xl"
128	        style={{ background: "radial-gradient(circle, rgba(111,71,245,0.5), transparent 70%)" }}
129	      />
130	      <div className="relative flex flex-wrap items-start justify-between gap-6">
131	        {/* Identity */}
132	        <div className="min-w-0">
133	          <div className="flex flex-wrap items-center gap-3">
134	            <div className="flex h-12 w-12 shrink-0 items-center justify-center overflow-hidden rounded-2xl border border-white/10" aria-hidden>
135	              <GameLogo family={gameFamily} size={48} />
136	            </div>
137	            <div className="min-w-0">
138	              <h1 className="truncate text-2xl font-bold tracking-tight text-white">{data.name}</h1>
139	              <div className="mt-1 flex flex-wrap items-center gap-2 text-xs text-slate-400">
140	                <span className="inline-flex items-center gap-1.5 font-medium">
141	                  <span
142	                    className="inline-block h-2 w-2 rounded-full"
143	                    style={{ background: tone.dot, boxShadow: tone.glow }}
144	                  />
145	                  <span className="text-slate-200">{tone.label}</span>
146	                </span>
147	                {data.customDomainVerified && data.customDomain && (
148	                  <button
149	                    onClick={() => copyAddr(data.customDomain!)}
150	                    className="rounded-md border border-emerald-500/20 bg-navy-950/70 px-2 py-0.5 font-mono text-[11px] text-emerald-300 transition-colors hover:border-emerald-400/50 hover:text-white"
151	                    title="Copy custom domain"
152	                  >
153	                    {copied === data.customDomain ? "copied ✓" : data.customDomain}
154	                  </button>
155	                )}
156	                {data.connect && (
157	                  <button
158	                    onClick={() => copyAddr(data.connect!)}
159	                    className="rounded-md border border-white/10 bg-navy-950/70 px-2 py-0.5 font-mono text-[11px] text-slate-300 transition-colors hover:border-brand-400/50 hover:text-white"
160	                    title="Copy connect address"
161	                  >
162	                    {copied === data.connect ? "copied ✓" : data.connect}
163	                  </button>
164	                )}
165	                {data.location && <span>· {data.location}</span>}
166	                <span className="font-mono text-slate-500">· {data.serverIdShort}</span>
167	              </div>
168	            </div>
169	          </div>
170	        </div>
171	
172	        {/* Vitals + actions */}
173	        <div className="flex flex-1 flex-wrap items-center justify-end gap-4">
174	          <div className="flex flex-wrap items-center gap-5">
175	            <Vital label="Players" value={`${playersOnline}${data.players.max ? ` / ${data.players.max}` : ""}`}>
176	              <div className="mt-1 h-1 w-16 overflow-hidden rounded-full bg-white/10">
177	                <div
178	                  className="h-full rounded-full bg-gradient-to-r from-accent-cyan to-brand-400"
179	                  style={{ width: `${data.players.max ? Math.min(100, (playersOnline / data.players.max) * 100) : 0}%` }}
180	                />
181	              </div>
182	            </Vital>
183	            <Vital label="CPU" value={`${data.cpuPct.toFixed(0)}%`}>
184	              <Sparkline id={`hdr-cpu-${serverId}`} data={cpuSeries} width={72} height={26} stroke="#8a70fb" />
185	            </Vital>
186	            <Vital label="RAM" value={`${fmtBytes(data.mem.usedBytes)} / ${fmtBytes(data.mem.maxBytes)}`}>
187	              <Sparkline id={`hdr-mem-${serverId}`} data={memSeries} width={72} height={26} stroke="#3b82f6" />
188	            </Vital>
189	            <Vital label="Disk" value={data.disk.usedGB > 0 ? `${data.disk.usedGB.toFixed(1)} / ${data.disk.maxGB} GB` : `${data.disk.maxGB} GB`}>
190	              <div className="mt-1 h-1 w-16 overflow-hidden rounded-full bg-white/10">
191	                <div className="h-full rounded-full bg-gradient-to-r from-amber-400 to-orange-500" style={{ width: `${Math.min(100, diskPct)}%` }} />
192	              </div>
193	            </Vital>
194	          </div>
195	
196	          <div className="flex items-center gap-2">
197	            <button
198	              onClick={copyConnect}
199	              disabled={!primaryConnect}
200	              className="btn-primary disabled:opacity-40"
201	              title={primaryConnect ? "Copy the connect address" : "Connect address not ready"}
202	            >
203	              {copied ? "Copied ✓" : "Connect"}
204	            </button>
205	            <button onClick={() => power("restart")} disabled={disabled} className="btn-secondary disabled:opacity-40">
206	              Restart
207	            </button>
208	            <button onClick={() => power("stop")} disabled={disabled} className="btn-danger disabled:opacity-40">
209	              Stop
210	            </button>
211	          </div>
212	        </div>
213	      </div>
214	
215	      {err && (
216	        <p className="relative mt-3 text-xs text-red-400" role="alert">
217	          {err}
218	        </p>
219	      )}
220	    </div>
