3	import { useState, useTransition } from "react";
4	import { serverAction } from "@/lib/actions";
5	
6	export function ServerControls({
7	  serverId,
8	  status,
9	  busy,
10	}: {
11	  serverId: string;
12	  status: string;
13	  busy: boolean;
14	}) {
15	  const [pending, startTransition] = useTransition();
16	  // serverAction returns { error } for anything the customer can act on. Called
17	  // bare, the message was discarded; a thrown error became Next's redacted generic
18	  // page. Either way the specific, actionable text never reached the screen.
19	  const [error, setError] = useState<string | null>(null);
20	  const disabled = pending || busy;
21	
22	  const run = (action: string, confirmMsg?: string) => {
23	    if (confirmMsg && !window.confirm(confirmMsg)) return;
24	    setError(null);
25	    startTransition(async () => {
26	      const res = await serverAction(serverId, action);
27	      if (res?.error) setError(res.error);
28	    });
29	  };
30	
31	  return (
32	    <div className="flex flex-col gap-2">
33	      <div className="flex flex-wrap gap-2">
34	      {status !== "RUNNING" && (
35	        <button className="btn-primary" disabled={disabled} onClick={() => run("start")}>
36	          Start
37	        </button>
38	      )}
39	      {status === "RUNNING" && (
40	        <>
41	          <button className="btn-secondary" disabled={disabled} onClick={() => run("reboot")}>
42	            Reboot
43	          </button>
44	          <button className="btn-secondary" disabled={disabled} onClick={() => run("stop")}>
45	            Stop
46	          </button>
47	        </>
48	      )}
49	      <button
50	        className="btn-secondary"
51	        disabled={disabled}
52	        onClick={() =>
53	          run("reinstall", "Reinstall wipes ALL data on this VPS and redeploys the OS. Continue?")
54	        }
55	      >
56	        Reinstall
57	      </button>
58	      <button
59	        className="btn-danger"
60	        disabled={disabled}
61	        onClick={() =>
62	          run("delete", "Permanently delete this VPS and all its data? This cannot be undone.")
63	        }
64	      >
65	        Delete
66	      </button>
67	      </div>
68	      {error && (
69	        <p className="text-xs text-red-400" role="alert">
70	          {error}
71	        </p>
72	      )}
73	    </div>
74	  );
75	}
