1	import { Fragment, type ReactNode } from "react";
2	
3	/**
4	 * Renders a ticket message body with light formatting — fenced code blocks,
5	 * inline code, and auto-highlighted IP addresses and domains — for both the
6	 * customer and admin ticket views (via EditableMessageBody).
7	 *
8	 * ─── WHY THIS IS BUILT FROM REACT ELEMENTS, NEVER innerHTML ──────────────────
9	 * A ticket body is UNTRUSTED input: customers type it. Rendering it through
10	 * `dangerouslySetInnerHTML` — even after a markdown pass — is a stored-XSS
11	 * vector (one crafted message runs script in a staff member's admin session).
12	 * So this tokenizes the raw string and emits ONLY text nodes and styled spans;
13	 * every character the user typed lands as text content, never as markup. The
14	 * "formatting" is pattern recognition over plain text, not HTML the user
15	 * supplied.
16	 *
17	 * Recognised, in order:
18	 *   1. ``` fenced code blocks ```  → a monospace <pre> block (verbatim).
19	 *   2. `inline code`               → a monospace chip (verbatim).
20	 *   3. http(s) URLs + bare domains → clickable links (new tab, noopener), in
21	 *      prose only. The href is ALWAYS one we built — the matched http(s) URL, or
22	 *      a bare domain we prefix with https:// — and is scheme-checked, so a
23	 *      `javascript:`/`data:` payload in a customer message can never become a
24	 *      link target.
25	 *   4. IPv4 (opt :port)            → a colored monospace chip (not clickable).
26	 * Code spans are left verbatim on purpose — a URL or IP inside a command should
27	 * read as part of the command, not get linkified/re-chipped.
28	 */
29	
30	// IPv4 with an optional :port. Octet-accurate so "8.3" or a version string can't
31	// masquerade as an address. Bounded by \b so it doesn't grab a trailing digit run.
32	const IP_SOURCE =
33	  "\\b(?:(?:25[0-5]|2[0-4]\\d|1?\\d?\\d)\\.){3}(?:25[0-5]|2[0-4]\\d|1?\\d?\\d)(?::\\d{1,5})?\\b";
34	// A domain: one or more labels then an ALPHA TLD (2–24). The alpha-TLD rule is
35	// what stops "php8.3", "0.0.0.0", or "e.g" from matching — a numeric last label
36	// is never a domain here.
37	const DOMAIN_SOURCE =
38	  "\\b(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\\.)+[a-zA-Z]{2,24}\\b";
39	// A full http(s) URL. Kept greedy to the first whitespace/quote/angle, then the
40	// trailing sentence punctuation is trimmed after the match (see trimUrlTail) so
41	// "see https://x.com/y." doesn't swallow the period into the link.
42	const URL_SOURCE = "https?://[^\\s<>\"'`]+";
43	// URL alternative FIRST (a URL contains a domain and could contain a dotted host),
44	// then IP so a dotted-quad is an IP not a failed domain, then bare domain.
45	const ENTITY_RE = new RegExp(`(${URL_SOURCE})|(${IP_SOURCE})|(${DOMAIN_SOURCE})`, "g");
46	
47	/** Trailing chars that are almost always sentence punctuation, not part of a URL. */
48	function trimUrlTail(url: string): { url: string; tail: string } {
49	  const m = /[.,;:!?)\]}'"]+$/.exec(url);
50	  // Keep a closing paren only if the URL also contains an opening one (wiki-style).
51	  if (!m) return { url, tail: "" };
52	  let cut = m[0];
53	  if (cut.includes(")") && (url.match(/\(/g)?.length ?? 0) >= (url.match(/\)/g)?.length ?? 0)) {
54	    cut = cut.replace(/\)+$/, "");
55	  }
56	  return cut ? { url: url.slice(0, url.length - cut.length), tail: cut } : { url, tail: "" };
57	}
58	
59	/**
60	 * Only ever produce an href we built ourselves from a matched http(s) URL or a
61	 * bare domain we prefix with https://. A user's text can never inject a
62	 * `javascript:`/`data:` scheme this way — the scheme is always http/https by
63	 * construction — but assert it anyway as defense in depth.
64	 */
65	function safeHref(href: string): string | null {
66	  return /^https?:\/\//i.test(href) ? href : null;
67	}
68	
69	const LINK_CLASS =
70	  "font-mono text-[0.95em] text-accent-blue underline decoration-dotted underline-offset-2 hover:text-brand-300 break-all";
71	
72	/** Highlight URLs (clickable), bare domains (clickable), and IPs (chip) in prose. */
73	function highlightEntities(text: string, keyBase: string): ReactNode[] {
74	  const out: ReactNode[] = [];
75	  let last = 0;
76	  let m: RegExpExecArray | null;
77	  ENTITY_RE.lastIndex = 0;
78	  let i = 0;
79	  while ((m = ENTITY_RE.exec(text)) !== null) {
80	    const isUrl = m[1] !== undefined;
81	    const isIp = m[2] !== undefined;
82	    let matchText = m[0];
83	    let tail = "";
84	    if (isUrl) {
85	      const trimmed = trimUrlTail(matchText);
86	      matchText = trimmed.url;
87	      tail = trimmed.tail;
88	    }
89	    if (m.index > last) out.push(text.slice(last, m.index));
90	
91	    if (isUrl || (!isIp && safeHref(`https://${matchText}`))) {
92	      // URL as-is; bare domain gets an https:// scheme for the href but shows raw.
93	      const href = safeHref(isUrl ? matchText : `https://${matchText}`);
94	      if (href) {
95	        out.push(
96	          <a key={`${keyBase}-e${i++}`} href={href} target="_blank" rel="noopener noreferrer nofollow" className={LINK_CLASS}>
97	            {matchText}
98	          </a>
99	        );
100	      } else {
101	        out.push(matchText);
102	      }
103	    } else {
104	      // IP address: informational chip, not a link.
105	      out.push(
106	        <span key={`${keyBase}-e${i++}`} className="rounded bg-accent-cyan/10 px-1 font-mono text-[0.9em] text-accent-cyan">
107	          {matchText}
108	        </span>
109	      );
110	    }
111	    if (tail) out.push(tail);
112	    last = m.index + m[0].length;
113	  }
114	  if (last < text.length) out.push(text.slice(last));
115	  return out;
116	}
117	
118	/** Split a prose run on `inline code`, highlighting entities in the gaps. */
119	function renderProse(text: string, keyBase: string): ReactNode[] {
120	  const parts = text.split(/(`[^`\n]+`)/g);
121	  return parts.map((part, idx) => {
122	    if (part.length >= 2 && part.startsWith("`") && part.endsWith("`")) {
123	      return (
124	        <code
125	          key={`${keyBase}-c${idx}`}
126	          className="rounded border border-white/10 bg-white/[0.06] px-1.5 py-0.5 font-mono text-[0.85em] text-slate-300"
127	        >
128	          {part.slice(1, -1)}
129	        </code>
130	      );
131	    }
132	    return <Fragment key={`${keyBase}-t${idx}`}>{highlightEntities(part, `${keyBase}-t${idx}`)}</Fragment>;
133	  });
134	}
135	
136	export function TicketBody({ text, className }: { text: string; className?: string }) {
137	  // Split on fenced code blocks. The capturing group keeps the fences' contents;
138	  // even indices are prose, odd indices are code-block bodies.
139	  const segments = text.split(/```([\s\S]*?)```/g);
140	
141	  return (
142	    <div className={className}>
143	      {segments.map((seg, idx) => {
144	        if (idx % 2 === 1) {
145	          // Fenced code block. Drop an optional leading language hint (```bash).
146	          const body = seg.replace(/^[ \t]*[a-zA-Z0-9_+-]*[ \t]*\n/, "").replace(/\n$/, "");
147	          return (
148	            <pre
149	              key={`b${idx}`}
150	              className="my-2 overflow-x-auto rounded-lg border border-white/10 bg-navy-950/80 p-3 font-mono text-xs leading-relaxed text-slate-200"
151	            >
152	              {body}
153	            </pre>
154	          );
155	        }
156	        if (seg === "") return null;
157	        return <Fragment key={`p${idx}`}>{renderProse(seg, `p${idx}`)}</Fragment>;
158	      })}
159	    </div>
160	  );
161	}
